const __pageData = JSON.parse('{"title":"Week 05 — Project 1: a validated scalar geolab baseline and a timing protocol","description":"","frontmatter":{"search":false,"prev":false,"next":false},"headers":[],"relativePath":"materials/week-05/PLAN.md","filePath":"materials/week-05/PLAN.md"}');
